settings.custom_liquid:
{%- liquid
  assign l = request.locale.iso_code
  case l
    when 'ar'
      assign t_h = 'الدفع بالتحويل البنكي'
      assign t_lead = 'انسخ كل معلومة بضغطة زر، أو امسح رمز GiroCode بتطبيق البنك. نشحن طلبك فور وصول الدفعة.'
      assign t_amount = 'المبلغ'
      assign t_name = 'المستفيد'
      assign t_ref = 'سبب التحويل'
      assign t_ref_none = 'رقم طلبك (B-Nr.)'
      assign t_copy = 'نسخ'
      assign t_done = 'تم النسخ ✓'
      assign t_qr = 'امسح الرمز بتطبيق البنك – تُملأ كل البيانات تلقائياً (SEPA).'
      assign t_note = 'يرجى كتابة سبب التحويل كما هو تماماً حتى نربط الدفعة بطلبك بسرعة.'
    when 'en'
      assign t_h = 'Payment by bank transfer'
      assign t_lead = 'Copy each detail with one tap, or scan the GiroCode with your banking app. We ship your order as soon as your payment is received.'
      assign t_amount = 'Amount'
      assign t_name = 'Account holder'
      assign t_ref = 'Reference'
      assign t_ref_none = 'Your order number (B-Nr.)'
      assign t_copy = 'Copy'
      assign t_done = 'Copied ✓'
      assign t_qr = 'Scan with your banking app – all details are filled in automatically (SEPA).'
      assign t_note = 'Please use the reference exactly as shown so we can match your payment quickly.'
    else
      assign t_h = 'Zahlung per Überweisung'
      assign t_lead = 'Kopieren Sie jede Angabe mit einem Klick oder scannen Sie den GiroCode mit Ihrer Banking-App. Wir versenden Ihre Bestellung, sobald die Zahlung eingegangen ist.'
      assign t_amount = 'Betrag'
      assign t_name = 'Empfänger'
      assign t_ref = 'Verwendungszweck'
      assign t_ref_none = 'Ihre Bestellnummer (B-Nr.)'
      assign t_copy = 'Kopieren'
      assign t_done = 'Kopiert ✓'
      assign t_qr = 'Mit Ihrer Banking-App scannen – Empfänger, IBAN, Betrag und Verwendungszweck werden automatisch übernommen.'
      assign t_note = 'Bitte geben Sie den Verwendungszweck genau so an, damit wir Ihre Zahlung schnell zuordnen können.'
  endcase
-%}
<div class="fhu page-width" dir="{% if l == 'ar' %}rtl{% else %}ltr{% endif %}" data-done="{{ t_done | escape }}" data-loc="{{ request.locale.iso_code }}">
  <div class="fhu__card">
    <p class="fhu__kick">Fragrance Hub Germany</p>
    <h1 class="fhu__h">{{ t_h }}</h1>
    <p class="fhu__lead">{{ t_lead }}</p>

    <div class="fhu__amount" data-amount-box hidden>
      <span class="fhu__lab">{{ t_amount }}</span>
      <span class="fhu__amt"><bdi data-amount-text></bdi></span>
      <button type="button" class="fhu__btn" data-copy-amount>{{ t_copy }}</button>
    </div>

    <dl class="fhu__rows">
      <div class="fhu__row">
        <dt class="fhu__lab">{{ t_name }}</dt>
        <dd class="fhu__val"><bdi>Fragrance Hub Germany</bdi></dd>
        <dd class="fhu__act"><button type="button" class="fhu__btn" data-copy="Fragrance Hub Germany">{{ t_copy }}</button></dd>
      </div>
      <div class="fhu__row">
        <dt class="fhu__lab">IBAN</dt>
        <dd class="fhu__val fhu__mono"><bdi>DE72 3002 0900 5371 0665 80</bdi></dd>
        <dd class="fhu__act"><button type="button" class="fhu__btn" data-copy="DE72300209005371066580">{{ t_copy }}</button></dd>
      </div>
      <div class="fhu__row">
        <dt class="fhu__lab">BIC</dt>
        <dd class="fhu__val fhu__mono"><bdi>CMCIDEDDXXX</bdi></dd>
        <dd class="fhu__act"><button type="button" class="fhu__btn" data-copy="CMCIDEDDXXX">{{ t_copy }}</button></dd>
      </div>
      <div class="fhu__row">
        <dt class="fhu__lab">Bank</dt>
        <dd class="fhu__val"><bdi>TARGOBANK</bdi></dd>
        <dd class="fhu__act"></dd>
      </div>
      <div class="fhu__row fhu__row--ref">
        <dt class="fhu__lab">{{ t_ref }}</dt>
        <dd class="fhu__val"><bdi class="fhu__ref" data-ref-text>{{ t_ref_none }}</bdi></dd>
        <dd class="fhu__act"><button type="button" class="fhu__btn" data-copy-ref hidden>{{ t_copy }}</button></dd>
      </div>
    </dl>
    <p class="fhu__note">{{ t_note }}</p>

    <div class="fhu__qr" data-qr-box hidden>
      <img data-qr-img width="200" height="200" alt="GiroCode">
      <p>{{ t_qr }}</p>
    </div>
  </div>
</div>

<style>
  .fhu{padding-top:36px;padding-bottom:56px}
  .fhu__card{max-width:640px;margin:0 auto;background:#FDF7EB;border:1px solid #E7E1D3;border-radius:12px;padding:28px 24px;box-shadow:0 8px 24px rgba(31,36,51,.06)}
  .fhu__kick{margin:0;font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:#8C6A22}
  .fhu__h{margin:6px 0 10px;font-size:28px;line-height:1.2;color:#1F2433}
  .fhu__lead{margin:0 0 20px;color:#4a4f5c;line-height:1.6}
  .fhu__amount{display:flex;align-items:center;gap:12px;flex-wrap:wrap;background:#1F2433;color:#FDF7EB;border-radius:10px;padding:14px 16px;margin-bottom:16px}
  .fhu__amount .fhu__lab{color:#D9BF7A}
  .fhu__amt{font-size:24px;font-weight:700;flex:1}
  .fhu__rows{margin:0;padding:0}
  .fhu__row{display:grid;grid-template-columns:minmax(110px,auto) 1fr auto;gap:6px 14px;align-items:center;padding:12px 0;border-bottom:1px solid #E7E1D3}
  .fhu__row dd{margin:0}
  .fhu__lab{font-size:13px;color:#6b6b6b}
  .fhu__val{font-size:16px;font-weight:600;color:#1F2433;word-break:break-word}
  .fhu__mono{font-variant-numeric:tabular-nums;letter-spacing:.02em}
  .fhu__ref{display:inline-block;background:#1F2433;color:#D9BF7A;border-radius:6px;padding:3px 10px}
  .fhu__btn{min-height:40px;min-width:92px;padding:0 14px;border-radius:8px;border:1px solid #B8963E;background:#fff;color:#1F2433;font:inherit;font-size:14px;font-weight:600;cursor:pointer}
  .fhu__btn:hover{background:#B8963E;color:#fff}
  .fhu__btn.is-done{background:#2e7d4f;border-color:#2e7d4f;color:#fff}
  .fhu__amount .fhu__btn{background:#B8963E;color:#1F2433;border-color:#B8963E}
  .fhu__note{margin:14px 0 0;font-size:13px;color:#6b6b6b}
  .fhu__qr{margin-top:22px;padding-top:20px;border-top:1px solid #E7E1D3;text-align:center}
  .fhu__qr img{display:block;margin:0 auto 10px;width:200px;height:200px;background:#fff;border-radius:8px;padding:6px}
  .fhu__qr p{margin:0;font-size:13px;color:#555}
  @media (max-width:560px){
    .fhu__row{grid-template-columns:1fr auto}
    .fhu__row .fhu__lab{grid-column:1 / -1}
    .fhu__h{font-size:24px}
  }
</style>

<script>
(function () {
  var root = document.querySelector('.fhu'); if (!root) return;
  var q = new URLSearchParams(location.search);
  var b = String(q.get('b') || '').replace(/\D/g, '').slice(0, 9);
  var a = String(q.get('a') || '').replace(',', '.').replace(/[^0-9.]/g, '');
  if (!/^\d{1,7}(\.\d{1,2})?$/.test(a) || Number(a) <= 0) a = '';
  var done = root.getAttribute('data-done') || '✓';
  var loc = root.getAttribute('data-loc') === 'de' ? 'de-DE' : (root.getAttribute('data-loc') === 'ar' ? 'de-DE' : 'en-GB');

  function copy(text, btn) {
    var ok = function () {
      var old = btn.textContent; btn.textContent = done; btn.classList.add('is-done');
      setTimeout(function () { btn.textContent = old; btn.classList.remove('is-done'); }, 1800);
    };
    if (navigator.clipboard && window.isSecureContext) {
      navigator.clipboard.writeText(text).then(ok, function () { fallback(text); ok(); });
    } else { fallback(text); ok(); }
  }
  function fallback(text) {
    var t = document.createElement('textarea'); t.value = text; t.setAttribute('readonly', '');
    t.style.position = 'fixed'; t.style.opacity = '0'; document.body.appendChild(t); t.select();
    try { document.execCommand('copy'); } catch (e) {} document.body.removeChild(t);
  }
  root.querySelectorAll('[data-copy]').forEach(function (btn) {
    btn.addEventListener('click', function () { copy(btn.getAttribute('data-copy'), btn); });
  });

  if (b) {
    var ref = 'B-Nr ' + b;
    root.querySelector('[data-ref-text]').textContent = ref;
    var rb = root.querySelector('[data-copy-ref]'); rb.hidden = false;
    rb.addEventListener('click', function () { copy(ref, rb); });
  }
  if (a) {
    var n = Number(a);
    root.querySelector('[data-amount-text]').textContent = n.toLocaleString(loc, { style: 'currency', currency: 'EUR' });
    root.querySelector('[data-amount-box]').hidden = false;
    var ab = root.querySelector('[data-copy-amount]');
    ab.addEventListener('click', function () { copy(n.toFixed(2).replace('.', loc === 'de-DE' ? ',' : '.'), ab); });
  }
  if (a && b) {
    var epc = ['BCD', '002', '1', 'SCT', 'CMCIDEDDXXX', 'Fragrance Hub Germany', 'DE72300209005371066580',
               'EUR' + Number(a).toFixed(2), '', '', 'B-Nr ' + b].join('\n');
    var img = root.querySelector('[data-qr-img]');
    img.src = 'https://api.qrserver.com/v1/create-qr-code/?size=400x400&ecc=M&margin=8&data=' + encodeURIComponent(epc);
    root.querySelector('[data-qr-box]').hidden = false;
  }
})();
</script>
